def grid(s):return [[int(v) for v in l.split()] for l in s.strip().splitlines() if l.strip() and all(v.isdigit() for v in l.split())]
def cc(g,bg):
 H,W=len(g),len(g[0]);s=set();cs=[]
 for r in range(H):
  for x in range(W):
   col=g[r][x]
   if col==bg or (r,x) in s:continue
   q=[(r,x)];s.add((r,x));ps=[]
   while q:
    a,b=q.pop();ps.append((a,b))
    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
     y,z=a+da,b+db
     if 0<=y<H and 0<=z<W and (y,z) not in s and g[y][z]==col:s.add((y,z));q.append((y,z))
   rs=[p[0] for p in ps];csx=[p[1] for p in ps];cs.append({'col':col,'n':len(ps),'box':(min(rs),min(csx),max(rs),max(csx)),'pts':set(ps)})
 return cs
