  g,o=grid(ins),grid(outs); bg=collections.Counter(sum(g,[])).most_common(1)[0][0]
  changes=[(r,x,g[r][x],o[r][x]) for r in range(len(g)) for x in range(len(g[0])) if g[r][x]!=o[r][x]]
  src,dst=changes[0][2],changes[0][3]; tpts={(r,x) for r,x,_,_ in changes}
  comps=cc(g,bg); targ=next((z for z in comps if z['pts']>=tpts),None)
