  def md(a,b):return min(abs(r-u)+abs(x-v) for r,x in a['pts'] for u,v in b['pts'])
  print(f'D{num} bg{bg}: target {src}->{dst} area {targ["n"] if targ else "?"} box {targ["box"] if targ else None}; marker candidates',[(z['n'],z['box'],md(z,targ) if targ else None) for z in dstc])
  print(' all:',[(z['col'],z['n'],z['box']) for z in comps])

